-- Markets & locations: every ISO 3166 country (PLANNED unless stated), the US launch set, Canada and the UK.
-- Regions carry capability switches; marketplace off implies everything off (table check constraint).


-- Version 1 is the published baseline; later changes are drafted and published by Marketing / Ops.
select 1, code, name, status, launch_note, currency, sort_order from market_country;
select 1, country, code, name, kind, marketplace, services, food, pickup, tax_registration, zip_prefixes from market_region;
